import unittest

from hourglass.models import Span
from hourglass.parsing import parse_span
from hourglass.rounding import round_span, rounded_labels


class RoundSpanTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        span = parse_span("09:07-17:08")
        self.assertEqual(
            round_span(span, 15), parse_span("09:00-17:15")
        )

    def test_halfway_rounds_up(self):
        self.assertEqual(
            round_span(Span(67, 128), 15), Span(75, 135)
        )

    def test_end_of_day_stays_valid(self):
        span = parse_span("22:00-23:58")
        self.assertEqual(
            round_span(span, 30), parse_span("22:00-24:00")
        )

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(61, 64), 15)


class LabelTests(unittest.TestCase):
    def test_labels(self):
        spans = [parse_span("09:02-17:14"), Span(600, 630)]
        self.assertEqual(
            rounded_labels(spans, 15),
            [
                "09:00-17:15 (8h 15m)",
                "10:00-10:30 (0h 30m)",
            ],
        )

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 15), [])

    def test_step_of_one_changes_nothing(self):
        self.assertEqual(
            rounded_labels([Span(61, 125)], 1),
            ["01:01-02:05 (1h 4m)"],
        )

    def test_bad_steps_raise(self):
        spans = [Span(60, 120)]
        for step in (0, -15, 7, 45, 61, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    rounded_labels(spans, step)

    def test_bad_step_raises_for_empty_list(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)


if __name__ == "__main__":
    unittest.main()
